import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfProf = () => {
  const { id } = useParams(); // Pega o ID do professor da URL
  const [professor, setProfessor] = useState(null);

  useEffect(() => {
    const fetchProfessor = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessor(dados);
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    fetchProfessor();
  }, [id]);

  // Verifica se o professor foi carregado
  if (!professor) return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="./admlistprof">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informação do Professor</h4>
          <p>
            <strong>{professor.nome}</strong>
          </p>
          <p>{professor.email}</p>
          <p>{professor.morada}</p>
          <p>{professor.contacto}</p>
        </div>

        <div className="w-50 ps-4">
          <label className="fw-bold">Cursos Atribuídos</label>
          <ul>
            {professor.cursos && professor.cursos.length > 0 ? (
              professor.cursos.map((curso) => (
                <li key={curso.id}>{curso.nome}</li>
              ))
            ) : (
              <li>Sem cursos atribuídos</li>
            )}
          </ul>
        </div>
      </div>
    </div>
  );
};

export default AdmInfProf;
